/bin/bash -lc "python3 - <<'PY'
import json, pathlib, re
manifest='/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54mini_all/first_10_queries/q04/logs/q04.manifest.json'
obj=json.load(open(manifest))

# capture explicit lower-court district judge name lines in captions
line_pat = re.compile(r'"'^(?P<name>.+?),'"\\s*(?:Hon\\.\\s*)?(?:(?:Chief|Senior)\\s+)?(?:United States |U\\.S\\. )?(District Judge|District Court|Chief District Judge|Senior District Judge), Presiding\\.?"'$'"')
line_pat2 = re.compile(r'"'^(?P<name>.+?),'"\\s*(?:Hon\\.\\s*)?(?:Chief\\s+|Senior\\s+)?(?:United States |U\\.S\\. )?District Judge\\.?"'$'"')
# also handle cases with District Judge + * footnote
line_pat3 = re.compile(r'"'^(?P<name>.+?),'"\\s*(?:Hon\\.\\s*)?(?:Chief\\s+|Senior\\s+)?(?:United States |U\\.S\\. )?District Judge\\.(?:\\s*\\*+)?"'$'"')

# first pass: explicit names and docket tokens
explicit = {}
token_to_name = {}
entries=[]
for d in obj['documents']:
    txt=pathlib.Path(d['doc_path']).read_text(errors='ignore')
    lines=[l.strip() for l in txt.splitlines()]
    name=None
    line_found=None
    for l in lines[:120]:
        if 'Magistrate Judge' in l or 'Bankruptcy' in l:
